from collections import Counter
def analyze(g):
    h,w=len(g),len(g[0])
    cnt=Counter(x for row in g for x in row)
    # colors touching each side
    sides={'T':Counter(), 'B':Counter(),'L':Counter(),'R':Counter()}
    for c in set(x for row in g for x in row):
        if c==0: continue
        if g[0][0]==c: sides['T'][c]+=1; sides['L'][c]+=1
        if g[0][-1]==c: sides['T'][c]+=1; sides['R'][c]+=1
        if g[-1][0]==c: sides['B'][c]+=1; sides['L'][c]+=1
        if g[-1][-1]==c: sides['B'][c]+=1; sides['R'][c]+=1
    return dict(cnt,sides=sides)
