def solve(g):
    h,w=len(g),len(g[0])
    cnt=Counter(x for row in g for x in row)
    mk=min(cnt,key=cnt.get)
    blks=[(r,c) for r in range(h-1) for c in range(w-1) 
          if g[r][c]==mk and g[r+1][c]==g[r][c+1]==g[r+1][c+1]==mk]
    # feature candidates -> value
    res={}
    # per-block ring composition (excl. block itself)
    for r,c in blks:
        nb=set()
        for dr in(-1,0,1):
            for dc in(-1,0,1):
                if (dr,dc)!=(0,0) and not(r<=r+dr<=r+1 and c<=c+dc<=c+1):
                    x,y=r+dr,c+dc
                    if 0<=x<h and 0<=y<w: nb.add(g[x][y])
        res['ring_maj_{}'.format(r)]=(max(nb,key=nb.count))
        res['ring_min{}'.format(r)]=min(nb,key=nb.count)
    # whole-grid stats
    res['top']=cnt.most_common(1)[0][0]
    res['second']=cnt.most_common(2)[1][0]
    # does dominant touch edge?
    def touches(col):
        return any(g[r][c]==col and (r==0 or r==h-1 or c==0 or c==w-1) for r in range(h) for c in range(w))
    res['dom_touche']=touches(res['top'])
    res['sec_touche']=touches(res['second'])
    return dict(sorted(res.items()))
